// ============================================================
// StockCheckPage.tsx
// 「株券」の入手条件を確認するページ。
// 種牡馬・繁殖牝馬(HorseRecord)カタログとは別に存在する株券データ
// (StockRecord/StockCard, stockCatalog.sample.ts) を一覧表示する。
//
// 画面構成:
//  ・種牡馬 / 繁殖牝馬 の切り替え（トグル）
//  ・馬名でのテキスト検索
//  ・レアリティでの表示絞り込み（複数選択可）
//  ・カラムヘッダークリックによる並び替え（馬名 / レアリティ / 必要sh）
//  ・1行 = 1株券（レアリティ単位）。同じ馬名でも複数行にまたがる
// ============================================================

import React, { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Container, Card, Form, Row, Col, Button,
  ToggleButton, ToggleButtonGroup, Table as BootstrapTable, Badge,
} from "react-bootstrap";
import { STOCK_CATALOG } from "./stockCatalog.sample";
import { StockCard, RARITY_COLOR, RARITY_TEXT_COLOR, ALL_RARITIES, rarityRank } from "./stockTypes";

// RARE は常に「株券合成」でのみ入手するため、入手条件チェックの対象からは除外する
const DISPLAY_RARITIES = ALL_RARITIES.filter((r) => r !== "RARE");

type SexFilter = "sire" | "mare";
type SortKey = "name" | "rarity" | "sh";
type SortDirection = "asc" | "desc";

interface FlatStockRow {
  /** 馬名+レアリティで一意（同名馬・重複レアリティが将来出てきても安全なように配列内indexも持たせる） */
  rowKey: string;
  horseName: string;
  card: StockCard;
}

const SORT_COMPARATORS: Record<SortKey, (a: FlatStockRow, b: FlatStockRow) => number> = {
  name: (a, b) => a.horseName.localeCompare(b.horseName, "ja"),
  rarity: (a, b) => rarityRank(a.card.rarity) - rarityRank(b.card.rarity),
  sh: (a, b) => a.card.sh - b.card.sh,
};

const StockCheckPage: React.FC = () => {
  const navigate = useNavigate();

  const [sexFilter, setSexFilter] = useState<SexFilter>("sire");
  const [searchText, setSearchText] = useState("");
  const [checkedRarities, setCheckedRarities] = useState<Record<string, boolean>>(
    Object.fromEntries(DISPLAY_RARITIES.map((r) => [r, true]))
  );
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: SortDirection } | null>(null);

  const flatRows = useMemo((): FlatStockRow[] => {
    const rows: FlatStockRow[] = [];
    STOCK_CATALOG
      .filter((h) => h.horse_type === sexFilter)
      .forEach((h, hIdx) => {
        h.cards
          .filter((c) => c.rarity !== "RARE")
          .forEach((c, cIdx) => {
            rows.push({ rowKey: `${hIdx}-${cIdx}`, horseName: h.name, card: c });
          });
      });
    return rows;
  }, [sexFilter]);

  const filteredRows = useMemo(() => {
    const keyword = searchText.trim();
    return flatRows.filter((r) => {
      if (keyword && !r.horseName.includes(keyword)) return false;
      if (!checkedRarities[r.card.rarity]) return false;
      return true;
    });
  }, [flatRows, searchText, checkedRarities]);

  const sortedRows = useMemo(() => {
    if (!sortConfig) {
      // デフォルト: 馬名 → レアリティ順
      return [...filteredRows].sort((a, b) => {
        const n = a.horseName.localeCompare(b.horseName, "ja");
        if (n !== 0) return n;
        return rarityRank(a.card.rarity) - rarityRank(b.card.rarity);
      });
    }
    const dir = sortConfig.direction === "asc" ? 1 : -1;
    const cmp = SORT_COMPARATORS[sortConfig.key];
    return [...filteredRows].sort((a, b) => cmp(a, b) * dir);
  }, [filteredRows, sortConfig]);

  const handleSort = (key: SortKey) => {
    setSortConfig((prev): { key: SortKey; direction: SortDirection } | null => {
      if (prev && prev.key === key) {
        return { key, direction: prev.direction === "asc" ? "desc" : "asc" };
      }
      return { key, direction: "asc" };
    });
  };
  const sortArrow = (key: SortKey) =>
    !sortConfig || sortConfig.key !== key ? "" : sortConfig.direction === "asc" ? " ▲" : " ▼";

  const backpage = () => navigate("/");

  const thStyle: React.CSSProperties = {
    backgroundColor: "#d32f2f", color: "#fff", padding: "10px 6px",
    border: "none", cursor: "pointer", whiteSpace: "nowrap", fontSize: "13px",
  };

  return (
    <div style={{ backgroundColor: "#f0f2f5", minHeight: "100vh", paddingBottom: "50px" }}>
      <Container className="pt-4" style={{ maxWidth: "920px" }}>
        <Card className="shadow border-0 mb-4" style={{ borderRadius: "16px", overflow: "hidden" }}>
          <div style={{ height: "8px", backgroundColor: "#d32f2f" }} />
          <Card.Body className="p-4">
            <h4 className="text-center mb-4" style={{ color: "#b71c1c", fontWeight: 900 }}>
              STOCK CHECK <span style={{ color: "#d32f2f", fontSize: "0.8em" }}>| 株券入手条件チェック</span>
            </h4>

            <Row className="mb-3">
              <Col xs={12} md={6} className="mb-3">
                <Form.Label className="small fw-bold text-muted">対象</Form.Label>
                <ToggleButtonGroup type="radio" name="sexFilter" value={sexFilter} className="w-100 shadow-sm">
                  <ToggleButton
                    id="stock-sire" value="sire"
                    variant={sexFilter === "sire" ? "dark" : "outline-dark"}
                    onClick={() => setSexFilter("sire")}
                    className="fw-bold"
                  >
                    種牡馬
                  </ToggleButton>
                  <ToggleButton
                    id="stock-mare" value="mare"
                    variant={sexFilter === "mare" ? "dark" : "outline-dark"}
                    onClick={() => setSexFilter("mare")}
                    className="fw-bold"
                  >
                    繁殖牝馬
                  </ToggleButton>
                </ToggleButtonGroup>
              </Col>
              <Col xs={12} md={6} className="mb-3">
                <Form.Label className="small fw-bold text-muted">馬名検索</Form.Label>
                <Form.Control
                  type="text"
                  placeholder="馬名の一部を入力"
                  value={searchText}
                  onChange={(e) => setSearchText(e.target.value)}
                  className="shadow-sm"
                />
              </Col>
            </Row>

            <Form.Label className="small fw-bold text-muted d-block">
              表示するレアリティ（クリックで表示/非表示を指定）
            </Form.Label>
            <div className="d-flex flex-wrap gap-2 mb-2">
              {DISPLAY_RARITIES.map((rarity) => (
                <ToggleButton
                  key={rarity}
                  id={`rarity-${rarity}`}
                  type="checkbox"
                  value={rarity}
                  checked={checkedRarities[rarity]}
                  onChange={(e) => setCheckedRarities({ ...checkedRarities, [rarity]: e.currentTarget.checked })}
                  className="fw-bold shadow-sm"
                  style={{
                    backgroundColor: checkedRarities[rarity] ? RARITY_COLOR[rarity] : "#e9ecef",
                    color: checkedRarities[rarity] ? RARITY_TEXT_COLOR[rarity] : "#6c757d",
                    border: "1px solid #ced4da",
                  }}
                >
                  {rarity}
                </ToggleButton>
              ))}
            </div>
          </Card.Body>
        </Card>

        <div className="shadow-sm mb-4" style={{ borderRadius: "12px", overflow: "hidden", overflowX: "auto" }}>
          <BootstrapTable className="mb-0" style={{ fontSize: "13px" }}>
            <thead>
              <tr className="text-center">
                <th style={{ ...thStyle, whiteSpace: "nowrap" }} onClick={() => handleSort("name")}>
                  馬名{sortArrow("name")}
                </th>
                <th style={{ ...thStyle, width: "60px" }} onClick={() => handleSort("rarity")}>
                  レア度{sortArrow("rarity")}
                </th>
                <th style={{ ...thStyle, width: "90px" }} onClick={() => handleSort("sh")}>
                  必要sh{sortArrow("sh")}
                </th>
                <th style={{ ...thStyle, cursor: "default" }}>セレブ</th>
                <th style={{ ...thStyle, cursor: "default" }}>入手条件</th>
              </tr>
            </thead>
            <tbody>
              {sortedRows.map((r) => (
                <tr key={r.rowKey} className="align-middle">
                  <td style={{ backgroundColor: "#3b3b3b", color: "#fff", fontWeight: 600, whiteSpace: "nowrap", padding: "8px" }}>
                    {r.horseName}
                  </td>
                  <td
                    className="text-center fw-bold"
                    style={{
                      backgroundColor: RARITY_COLOR[r.card.rarity] ?? "#ffffff",
                      color: RARITY_TEXT_COLOR[r.card.rarity] ?? "#333",
                      padding: "8px 4px",
                    }}
                  >
                    {r.card.rarity}
                  </td>
                  <td className="text-center" style={{ backgroundColor: "#ffff9e", padding: "8px 4px" }}>
                    {r.card.sh_text}
                  </td>
                  <td style={{ backgroundColor: "#ffffff", padding: "8px" }}>
                    {r.card.celeb ? <Badge bg="warning" text="dark">{r.card.celeb}</Badge> : <span className="text-muted">―</span>}
                  </td>
                  <td style={{ backgroundColor: "#ffffff", padding: "8px" }}>
                    {r.card.conditions.map((c, i) => (
                      <div key={i} className="mb-1">
                        <Badge bg="secondary" className="me-1">{c.label}</Badge>
                        {c.text}
                      </div>
                    ))}
                  </td>
                </tr>
              ))}
              {sortedRows.length === 0 && (
                <tr>
                  <td colSpan={5} className="text-center text-muted py-3" style={{ backgroundColor: "#fff" }}>
                    条件に一致する株券がありません
                  </td>
                </tr>
              )}
            </tbody>
          </BootstrapTable>
        </div>

        <Button variant="success" className="w-100 fw-bold py-2 shadow-sm" style={{ borderRadius: "10px" }} onClick={backpage}>
          戻る
        </Button>
      </Container>
    </div>
  );
};

export default StockCheckPage;
