// ============================================================
// homebredValidation.ts
// 「その自家生産馬は本当に作れるのか」を検証するユーティリティ。
//
// 血統ツリーに置かれた自家生産馬は、それ自身が 父 × 母 の配合で
// 生産された馬なので、その父母の組み合わせが配合不可（1×2 / 2×3 /
// 3×3 と 2×4 の合計2つ以上 など）であれば、その馬は本来存在しえない。
//
// 判定は「その自家生産馬を本馬とみなして、父側4代・母側4代を突き合わせる」
// 形で行う。これは実際にその馬を生産したときにゲーム側が行った判定と
// 同じ条件であり、画面上部の 1対1 判定（judgePair）と同一のロジック
// （flattenPedigree → detectInbreedPairs → judgeInbreed）を使う。
//
// ※ 表示上の血統表は本馬から4代までしか描画されないが、この検証では
//   各自家生産馬から見た4代を改めて展開するため、画面に出ていない
//   世代の重複も正しく検出される。
// ============================================================

import { InbreedPair, PedigreeNode } from "./types";
import {
  detectInbreedPairs,
  flattenPedigree,
  judgeInbreed,
  resolveNodeIdentity,
} from "./pedigreeUtils";

/** ルートからのパス。"S"=父方へ1つ, "D"=母方へ1つ。空配列＝本馬自身 */
export type NodePath = ("S" | "D")[];

/** 検出された「作れない自家生産馬」1件 */
export interface HomebredIssue {
  /** ツリー内での位置 */
  path: NodePath;
  /** 位置の表示名（"本馬" / "父" / "母の父" など） */
  positionLabel: string;
  /** その自家生産馬の表示名 */
  horseLabel: string;
  /** 配合不可の理由 */
  reason: string;
  /** 原因となった重複ペア（表示用） */
  pairs: InbreedPair[];
}

export interface HomebredJudgeResult {
  isValid: boolean;
  reason?: string;
  pairs: InbreedPair[];
}

/** パスから位置の見出しを作る（例: ["S","D"] → "父の母"） */
export function pathPositionLabel(path: NodePath): string {
  if (path.length === 0) return "本馬";
  return path.map((p) => (p === "S" ? "父" : "母")).join("の");
}

/**
 * 自家生産馬1頭について、その父×母が配合可能かを判定する。
 * 自家生産馬でない場合、または父母のどちらかが未設定（4代目など）の場合は null。
 */
export function judgeHomebredNode(
  node: PedigreeNode | null | undefined
): HomebredJudgeResult | null {
  if (!node || node.type !== "homebred") return null;
  if (!node.sire || !node.dam) return null;

  // 父と母が同一個体（保存した自家生産馬を父・母の両方に置いた場合など）は
  // そもそも生産できないため、インブリード判定より先に弾く。
  const sireId = resolveNodeIdentity(node.sire);
  const damId = resolveNodeIdentity(node.dam);
  if (sireId && damId && sireId.key === damId.key) {
    return {
      isValid: false,
      reason: `父と母が同一の個体（${sireId.label}）です`,
      pairs: [],
    };
  }

  const sireAncestors = flattenPedigree(node.sire, 1);
  const damAncestors = flattenPedigree(node.dam, 1);
  const pairs = detectInbreedPairs(sireAncestors, damAncestors);
  const result = judgeInbreed(pairs);

  return { isValid: result.isValid, reason: result.invalidReason, pairs };
}

/**
 * 血統ツリー内の全ての自家生産馬を検査し、「作れない馬」を一覧で返す。
 * カタログ馬（実在馬）はゲーム内に存在する馬なので検査対象外。
 */
export function collectHomebredIssues(
  node: PedigreeNode | null | undefined,
  path: NodePath = [],
  out: HomebredIssue[] = []
): HomebredIssue[] {
  if (!node || node.type !== "homebred") return out;

  const judged = judgeHomebredNode(node);
  if (judged && !judged.isValid) {
    out.push({
      path: [...path],
      positionLabel: pathPositionLabel(path),
      horseLabel: node.name?.trim() || "自家生産馬",
      reason: judged.reason ?? "配合不可の組み合わせです",
      pairs: judged.pairs,
    });
  }

  collectHomebredIssues(node.sire, [...path, "S"], out);
  collectHomebredIssues(node.dam, [...path, "D"], out);
  return out;
}

/** ツリー内に「作れない自家生産馬」が1頭でもいるか */
export function hasHomebredIssue(node: PedigreeNode | null | undefined): boolean {
  return collectHomebredIssues(node).length > 0;
}

/** 血統表のマスをエラー表示するためのキー集合（path.join("") / ルートは "root"） */
export function issuePathKeys(issues: HomebredIssue[]): Set<string> {
  return new Set(issues.map((i) => i.path.join("") || "root"));
}

/**
 * 2つのパスが「一方が他方の先祖（プレフィックス）」の関係にあるか。
 * あるマスの選択によって影響を受ける自家生産馬は、
 *  ・そのマスより上の自家生産馬（父母構成が変わる）
 *  ・そのマスに入る馬自身とその配下（持ち込まれる血統）
 * のいずれかなので、この関係で絞り込む。
 */
export function isRelatedPath(a: NodePath, b: NodePath): boolean {
  const short = a.length <= b.length ? a : b;
  const long = a.length <= b.length ? b : a;
  return short.every((v, i) => v === long[i]);
}
