/** 適性の段階。◎ > ○ > 無印 > ×（ボーナス方向） */
export type AptitudeMark = "◎" | "○" | "×";

export interface InbreedEffectRow {
  /** インブリード対象馬名（表示用のメイン名、日本語） */
  name: string;
  /**
   * 血統表上での別表記（英語名など）。HORSE_CATALOG の pedigree では
   * 海外の祖先が英語表記で登録されていることが多く、name（日本語）だけでは
   * 一致せずクロスが検出できないケースがあるため、実データで確認できた
   * 英語表記をここに追加している。name に加えてこれらの表記でもマッチする。
   */
  aliases?: string[];
  aptitudes: Partial<Record<
    | "気性" | "距離適性" | "芝" | "ダート" | "AW" | "道悪"
    | "右回り" | "左回り" | "小回り" | "遠征" | "坂",
    string
  >>;
}

