import React, { useState, useMemo } from 'react';
import { Container, Card, Form, Table, Button } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import * as Data from './SelectData'; 

/**
 * レースグレードに応じて表示するカラム（列）の構成を定義
 */
const getTableColumns = (grade: string) => {
  switch (grade) {
    case '2000': // WBC
      return [
        { pre: '0',   label: '恩恵無', color: '#6c757d' },
        { pre: '0.5', label: 'G1 2着', color: '#e63946' },
        { pre: '1',   label: 'G1 1勝', color: '#2a9d8f' },
        { pre: '1.5', label: '1勝+2着', color: '#f4a261' },
        { pre: '2',   label: 'G1 2勝', color: '#457b9d' },
      ];
    case '5000': // SWBC
      return [
        { pre: '1',   label: 'G1 1勝', color: '#2a9d8f' },
        { pre: '1.5', label: '1勝+2着', color: '#f4a261' },
        { pre: '2',   label: 'G1 2勝', color: '#457b9d' },
      ];
    case '160':
    case '200': // G2確認
      return [
        { pre: '4',   label: 'G2確認', color: '#457b9d' },
      ];
    case '400':
    case '500':
    default: // 400枚・500枚G1など
      return [
        { pre: '1',   label: '1着', color: '#e63946' },
        { pre: '2',   label: '2着', color: '#2a9d8f' },
        { pre: '3',   label: '3着', color: '#f4a261' },
        { pre: '4',   label: '未出走', color: '#457b9d' },
      ];
  }
};

const HanteiAllView: React.FC = () => {
  const navigate = useNavigate();
  
  // viewlist="true" のレース一覧を取得
  const filteredRaceList = useMemo(() => {
    return Data.StartRaceData.filter(race => race.viewlist === "true");
  }, []);

  // 初期表示をWBC(2000)に設定。なければリストの先頭。
  const initialGrade = useMemo(() => {
    const wbc = filteredRaceList.find(r => r.grade === '2000');
    return wbc ? wbc.grade : (filteredRaceList[0]?.grade || '');
  }, [filteredRaceList]);

  const [selectedGrade, setSelectedGrade] = useState<string>(initialGrade);

  // 選択されたグレードに応じたユニークな素質名リスト
  const uniqueComms = useMemo(() => {
    const comms = Data.SoshitsuData
      .filter(d => d.grade === selectedGrade)
      .map(d => d.comm);
    return Array.from(new Set(comms));
  }, [selectedGrade]);

  // 特定の条件（素質名・着順ID）からデータを抽出
  const getData = (comm: string, pre: string) => {
    return Data.SoshitsuData.find(d => 
      d.grade === selectedGrade && d.comm === comm && d.pre === pre
    );
  };

  // 現在のグレードに最適なカラム設定を取得
  const currentColumns = useMemo(() => getTableColumns(selectedGrade), [selectedGrade]);

  // テーブルの最低幅を動的に計算（1カラム110px + 素質名90px）
  const tableMinWidth = `${currentColumns.length * 110 + 90}px`;

  return (
    <div style={{ backgroundColor: '#f0f2f5', minHeight: '100vh', paddingBottom: '50px' }}>
      <Container className="pt-3 px-2" style={{ maxWidth: '100%' }}>
        
        <div className="text-center mb-3">
          <h5 style={{ color: '#444', fontWeight: '800', margin: 0 }}>
            素質・着順別オッズ一覧
          </h5>
        </div>

        {/* レース選択カード */}
        <Card className="shadow-sm border-0 mb-3" style={{ borderRadius: '12px', overflow: 'hidden' }}>
          <div style={{ height: '4px', backgroundColor: '#3bc0bd' }}></div>
          <Card.Body className="p-3">
            <Form.Select 
              value={selectedGrade} 
              onChange={(e) => setSelectedGrade(e.target.value)}
              className="border-0 bg-light fw-bold shadow-none"
              style={{ borderRadius: '8px', fontSize: '0.9rem' }}
            >
              {filteredRaceList.map((race) => (
                <option key={race.id} value={race.grade}>{race.racename}</option>
              ))}
            </Form.Select>
          </Card.Body>
        </Card>

        {/* テーブルエリア */}
        <div className="table-responsive shadow-sm" style={{ borderRadius: '12px', overflowX: 'auto', WebkitOverflowScrolling: 'touch' }}>
          <Table className="mb-0 text-center" style={{ verticalAlign: 'middle', border: 'none', minWidth: tableMinWidth, tableLayout: 'fixed' }}>
            <thead className="text-white" style={{ fontSize: '0.75rem' }}>
              <tr>
                {/* 固定素質名カラム（スマホスクロール用） */}
                <th rowSpan={2} style={{ 
                  position: 'sticky', left: 0, zIndex: 10, 
                  backgroundColor: '#444', width: '90px', 
                  borderRight: '2px solid #555', verticalAlign: 'middle',
                  color: '#FFFFFF'
                }}>素質</th>
                
                {/* 動的ヘッダー：着順・条件名 */}
                {currentColumns.map((col, idx) => (
                  <th key={`h-${idx}`} colSpan={2} style={{ backgroundColor: col.color, borderLeft: '1px solid rgba(255,255,255,0.1)' }}>
                    {col.label}
                  </th>
                ))}
              </tr>
              <tr style={{ fontSize: '0.65rem', opacity: 0.9 }}>
                {/* 動的サブヘッダー：単勝/ライド */}
                {currentColumns.map((col, idx) => (
                  <React.Fragment key={`sh-${idx}`}>
                    <th style={{ backgroundColor: col.color, borderLeft: '1px solid rgba(255,255,255,0.1)' }}>単</th>
                    <th style={{ backgroundColor: col.color }}>R</th>
                  </React.Fragment>
                ))}
              </tr>
            </thead>
            <tbody style={{ fontSize: '0.85rem' }}>
              {uniqueComms.length > 0 ? (
                uniqueComms.map((comm, index) => {
                  const rowBg = index % 2 === 0 ? '#2c2c2c' : '#3d3d3d';

                  return (
                    <tr key={comm} style={{ borderBottom: '1px solid #555' }}>
                      <td style={{ 
                        position: 'sticky', left: 0, zIndex: 5,
                        backgroundColor: rowBg, color: '#FFFFFF', 
                        fontWeight: 'bold', textAlign: 'center', 
                        borderRight: '2px solid #555', fontSize: '0.8rem'
                      }}>
                        {comm}
                      </td>
                      {/* 動的に各着順のデータを流し込む */}
                      {currentColumns.map((col, idx) => {
                        const d = getData(comm, col.pre);
                        return (
                          <React.Fragment key={`c-${idx}`}>
                            <td style={{ backgroundColor: rowBg, color: '#fffa00', fontWeight: 'bold', borderLeft: '1px solid #555' }}>
                              {d ? d.win : '-'}
                            </td>
                            <td style={{ backgroundColor: rowBg, color: '#bbb', fontSize: '0.7rem' }}>
                              {d ? (d.win_r === '0' || !d.win_r ? '-' : d.win_r) : '-'}
                            </td>
                          </React.Fragment>
                        );
                      })}
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={currentColumns.length * 2 + 1} className="text-center p-4 bg-dark text-white">
                    データが存在しません
                  </td>
                </tr>
              )}
            </tbody>
          </Table>
        </div>

        <div className="mt-4 px-1">
          <Button variant="secondary" className="w-100 fw-bold py-2 shadow-sm" style={{ borderRadius: '10px', fontSize: '0.9rem' }} onClick={() => navigate(-1)}>
            戻る
          </Button>
        </div>
      </Container>
    </div>
  );
};

export default HanteiAllView;