import React, { useState } from 'react';
import { HorseIDData } from './TaneData';
import { useNavigate } from "react-router-dom";
import { Container, Form, Button, Row, Col, Card, Table as BootstrapTable, ToggleButton, ToggleButtonGroup } from 'react-bootstrap';

const Table: React.FC = () => {
    const navigate = useNavigate();
    const [horseList] = useState(HorseIDData);
    const [filteredHorseList, setFilteredHorseList] = useState(HorseIDData);
    const [checkFlg, setCheckFlg] = useState<boolean>(false); 
    
    const [selectedHorseId_1, setSelectedHorseId_1] = useState<string>("B09");
    const [selectedHorseId_2, setSelectedHorseId_2] = useState<string>("B09");

    const handleSelectChange_1 = (event: React.ChangeEvent<HTMLSelectElement>) => {
        setSelectedHorseId_1(event.target.value);
    };
    const handleSelectChange_2 = (event: React.ChangeEvent<HTMLSelectElement>) => {
        setSelectedHorseId_2(event.target.value);
    };

    const [category, setCategory] = useState<"stallion" | "mare">("mare");
    const handleCategoryChange = (val: "stallion" | "mare") => {
        setCategory(val);
        const defaultId = val === "mare" ? "B09" : "A22";
        setSelectedHorseId_1(defaultId);
        setSelectedHorseId_2(defaultId);
    };

    const [line, setLine] = useState<"singleLine" | "doubleLine">("singleLine");
    const handleLineChange = (val: "singleLine" | "doubleLine") => {
        setLine(val);
    };

    const filteredDataA = HorseIDData
        .filter(a => category === "stallion" ? a.horseID.startsWith("A") : a.horseID.startsWith("B"))
        .sort((a, b) => a.horseKeitou.localeCompare(b.horseKeitou));

    const [checkedItems, setCheckedItems] = useState<{ [key: string]: boolean }>({
        "堅実": true, "平均": false, "一発": false
    });

    type bdData = {
        horseID: string; 
        horseKeitou: string; 
        aisyo: string;
        memo: string;
    };
    const [sortConfig, setSortConfig] = useState<{ key: keyof bdData; direction: "asc" | "desc" } | null>(null);

    const sortedData = [...filteredHorseList].sort((a, b) => {
        if (!sortConfig) return 0;
        const { key, direction } = sortConfig;
        const order = direction === "asc" ? 1 : -1;
        const valA = a[key] || "";
        const valB = b[key] || "";
        return valA.localeCompare(valB) * order;
    });

    const handleSort = (key: keyof bdData) => {
        setSortConfig((prev) => {
            if (prev && prev.key === key) {
                return { key, direction: prev.direction === "asc" ? "desc" : "asc" };
            }
            return { key, direction: "asc" };
        });
    };

    const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        if (!checkedItems["堅実"] && !checkedItems["平均"] && !checkedItems["一発"]) {
            alert('1つ以上チェックしてください！');
            return;
        }
        setCheckFlg(true);

        const hList = horseList.filter(a => category === "stallion" ? a.horseID.startsWith("B") : a.horseID.startsWith("A"));
        const horseData1 = HorseIDData.find(a => a.horseID === selectedHorseId_1);
        const horseData2 = HorseIDData.find(a => a.horseID === selectedHorseId_2);
        
        if (!horseData1 || !horseData2) return;

        const keito_1 = horseData1.aisyo.split('');
        const keito_2 = horseData2.aisyo.split('');

        const tete = hList.map((i) => {
            const tempItem = { ...i, memo: "" };
            const getHaigoId = Number(tempItem.horseID.replace("A", "").replace("B", ""));
            const haigoPln_1 = keito_1[getHaigoId - 1];
            const haigoPln_2 = keito_2[getHaigoId - 1];

            const checkMatch = (p1: string, p2: string) => {
                if (line === 'singleLine') return p1;
                return (p1 === p2) ? p1 : null;
            };

            const resultPln = checkMatch(haigoPln_1, haigoPln_2);

            if (resultPln === "1" && checkedItems["堅実"]) {
                tempItem.memo = "堅実";
                if (line === 'singleLine' && (tempItem as any).memo1.split(",").includes(horseData1.horseID)) tempItem.memo = "鉄板";
                return tempItem;
            } else if (resultPln === "2" && checkedItems["平均"]) {
                tempItem.memo = "平均";
                return tempItem;
            } else if (resultPln === "3" && checkedItems["一発"]) {
                tempItem.memo = "一発";
                if (line === 'singleLine' && (tempItem as any).memo3.split(",").includes(horseData1.horseID)) tempItem.memo = "爆発";
                return tempItem;
            }
            return null;
        }).filter((i): i is any => i !== null);

        setFilteredHorseList(tete);
    }

    const backpage = () => { navigate("/"); };

    return (
        <div style={{ backgroundColor: '#f0f2f5', minHeight: '100vh', paddingBottom: '50px' }}>
            <Container className="pt-4" style={{ maxWidth: '700px' }}>
                <Card className="shadow border-0 mb-4" style={{ borderRadius: '16px', overflow: 'hidden' }}>
                    <div style={{ height: '8px', backgroundColor: '#d32f2f' }}></div>
                    <Card.Body className="p-4">
                        <h4 className="text-center mb-4" style={{ color: '#b71c1c', fontWeight: '900', letterSpacing: '1px' }}>
                            AFFINITY CHECK <span style={{ color: '#d32f2f', fontSize: '0.8em', fontWeight: 'bold' }}>| 血統相性チェック</span>
                        </h4>

                        <Form onSubmit={handleSubmit}>
                            <Row className="mb-3">
                                <Col xs={12} md={6} className="mb-3">
                                    <Form.Label className="small fw-bold text-muted">相手の性別</Form.Label>
                                    <ToggleButtonGroup type="radio" name="category" value={category} className="w-100 shadow-sm">
                                        <ToggleButton id="tgl-stallion" value="stallion" variant={category === "stallion" ? "dark" : "outline-dark"} onClick={() => handleCategoryChange("stallion")} className="fw-bold">種牡馬</ToggleButton>
                                        <ToggleButton id="tgl-mare" value="mare" variant={category === "mare" ? "dark" : "outline-dark"} onClick={() => handleCategoryChange("mare")} className="fw-bold">繁殖牝馬</ToggleButton>
                                    </ToggleButtonGroup>
                                </Col>
                                <Col xs={12} md={6} className="mb-3">
                                    <Form.Label className="small fw-bold text-muted">検索モード</Form.Label>
                                    <ToggleButtonGroup type="radio" name="line" value={line} className="w-100 shadow-sm">
                                        <ToggleButton id="tgl-single" value="singleLine" variant={line === "singleLine" ? "dark" : "outline-dark"} onClick={() => handleLineChange("singleLine")} className="fw-bold">通常</ToggleButton>
                                        <ToggleButton id="tgl-double" value="doubleLine" variant={line === "doubleLine" ? "dark" : "outline-dark"} onClick={() => handleLineChange("doubleLine")} className="fw-bold">複数系統</ToggleButton>
                                    </ToggleButtonGroup>
                                </Col>
                            </Row>

                            <Row className="mb-4">
                                <Col xs={12} md={line === 'doubleLine' ? 6 : 12} className="mb-3">
                                    <Form.Label htmlFor="select-1" className="small fw-bold text-muted">系統１</Form.Label>
                                    <Form.Select id="select-1" value={selectedHorseId_1} onChange={handleSelectChange_1} className="shadow-sm">
                                        {filteredDataA.map((item) => (
                                            <option key={item.horseID} value={item.horseID}>{item.horseKeitou}</option>
                                        ))}
                                    </Form.Select>
                                </Col>
                                {line === 'doubleLine' && (
                                    <Col xs={12} md={6} className="mb-3">
                                        <Form.Label htmlFor="select-2" className="small fw-bold text-muted">系統２</Form.Label>
                                        <Form.Select id="select-2" value={selectedHorseId_2} onChange={handleSelectChange_2} className="shadow-sm">
                                            {filteredDataA.map((item) => (
                                                <option key={item.horseID} value={item.horseID}>{item.horseKeitou}</option>
                                            ))}
                                        </Form.Select>
                                    </Col>
                                )}
                            </Row>

                            <div className="mb-4">
                                <Form.Label className="small fw-bold text-muted">表示オプション</Form.Label>
                                <div className="d-flex gap-2">
                                    {[
                                        { label: "堅実", variant: "primary" },
                                        { label: "平均", variant: "warning" },
                                        { label: "一発", variant: "danger" }
                                    ].map((item) => (
                                        <ToggleButton
                                            key={item.label}
                                            id={`check-${item.label}`}
                                            type="checkbox"
                                            value={item.label}
                                            variant={checkedItems[item.label] ? item.variant : `outline-${item.variant}`}
                                            checked={checkedItems[item.label]}
                                            onChange={(e) => setCheckedItems({...checkedItems, [item.label]: e.currentTarget.checked})}
                                            className="flex-fill fw-bold shadow-sm"
                                            style={{ color: (checkedItems[item.label] && item.label === "平均") ? "#333" : "" }}
                                        >
                                            {item.label}
                                        </ToggleButton>
                                    ))}
                                </div>
                            </div>

                            <Button type="submit" className="w-100 border-0 shadow mb-3" 
                                style={{ 
                                    background: 'linear-gradient(45deg, #d32f2f 0%, #b71c1c 100%)', 
                                    borderRadius: '10px', padding: '12px', fontWeight: 'bold'
                                }}>
                                検索！
                            </Button>
                        </Form>
                    </Card.Body>
                </Card>

                {checkFlg && (
                    <div className="shadow-sm mb-4" style={{ borderRadius: '12px', overflow: 'hidden' }}>
                        <BootstrapTable className="mb-0" style={{ fontSize: "14px" }}>
                            <thead>
                                <tr className="text-center">
                                    <th onClick={() => handleSort("horseKeitou")} style={{ backgroundColor: '#d32f2f', color: '#ffffff', cursor: "pointer", padding: '14px', border: 'none' }}>
                                        系統名 {sortConfig?.key === "horseKeitou" ? (sortConfig.direction === "asc" ? "▲" : "▼") : ""}
                                    </th>
                                    <th onClick={() => handleSort("memo")} style={{ backgroundColor: '#d32f2f', color: '#ffffff', cursor: "pointer", padding: '14px', border: 'none' }}>
                                        相性 {sortConfig?.key === "memo" ? (sortConfig.direction === "asc" ? "▲" : "▼") : ""}
                                    </th>
                                </tr>
                            </thead>
                            <tbody>
                                {sortedData.map((data, index) => (
                                    <tr key={index} className="text-center align-middle">
                                        <td style={{ backgroundColor: '#3b3b3b', color: '#ffffff', fontWeight: '600', borderColor: '#4a4a4a' }}>{data.horseKeitou}</td>
                                        <td style={{
                                            backgroundColor:
                                                data.memo === '堅実' ? '#80bfff' : 
                                                data.memo === '平均' ? '#ffff9e' : 
                                                data.memo === '一発' ? '#ff9e9e' : 
                                                data.memo === '鉄板' ? '#0080ff' : 
                                                data.memo === '爆発' ? '#ff3333' : '#ffffff',
                                            // 堅実と鉄板の文字色を黒(#333)に変更、爆発は白文字を維持
                                            color: (data.memo === '爆発') ? '#ffffff' : '#333333',
                                            fontWeight: 'bold',
                                            borderColor: '#4a4a4a'
                                        }}>
                                            {data.memo}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </BootstrapTable>
                    </div>
                )}

                <Button variant="success" className="w-100 fw-bold py-2 shadow-sm" style={{ borderRadius: '10px' }} onClick={backpage}>
                    戻る
                </Button> 
            </Container>
        </div>
    );
};

export default Table;