import React from 'react';
import { Suspense, lazy } from 'react';
import { HashRouter as Router, Route, Routes } from 'react-router-dom';
import Home from './Home';
import TableOld from './TableOld';
import Table from './Table';
import Test from './Test';
import Hantei from './Hantei';
import Hantei_b from './Hantei_b';
import Blood from './Blood';
import Schedule from './Schedule';
import QrRead from './QrRead';
import QrUpdate from './QrUpdate';
import QrHome from './QrHome';
import Win from './Win';
import WbcRival from './WbcRival';
import Senduipath from './Senduipath';
import Navbar from './components/Navbar';
import InbreedCheckPage from './InbreedCheckPage';
import StockCheckPage from './StockCheckPage';

import 'bootstrap/dist/css/bootstrap.min.css';

// 独立機能のため遅延読み込みにしておく（初期バンドルを膨らませない）
const BoatraceApp = lazy(() => import('./boatrace/BoatraceApp'));


const App: React.FC = () => {
  return (
    // HashRouter を使うので basename は不要
    <Router>
      <Navbar /> {/* ナビバーがある場合はここに配置 */}

      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/table" element={<Table />} />
        <Route path="/hantei" element={<Hantei />} />
        <Route path="/hantei_b" element={<Hantei_b />} />
        <Route path="/test" element={<Test />} />
        <Route path="/blood" element={<Blood />} />
        <Route path="/schedule" element={<Schedule />} />
        <Route path="/win" element={<Win />} />
        <Route path="/senduipath" element={<Senduipath />} />
        <Route path="/qrread" element={<QrRead />} />
        <Route path="/qrhome" element={<QrHome />} />
        <Route path="/qrupdate" element={<QrUpdate />} />
        <Route path="/wbcrival" element={<WbcRival />} />

        <Route path="/inbreedcheck" element={<InbreedCheckPage />} />
        <Route path="/stockcheck" element={<StockCheckPage />} />
        <Route path="/boatrace/*" element={<Suspense fallback={<div>読み込み中…</div>}><BoatraceApp /></Suspense>}/>

        {/* 404 対応も追加可能 */}
        <Route path="*" element={<Home />} />
      </Routes>
    </Router>
  );
};

export default App;