// ============================================================
// PedigreeGridSelector.tsx
// 血統指定UI（旧 PedigreeNodeSelector.tsx の置き換え）。
//
// 変更のねらい:
//  ・入れ子カードで縦に伸びていた選択UIをやめ、競馬の血統表と同じ
//    「4代グリッド」を常時表示する。全体像が1画面で把握できる。
//  ・各マスをクリック（タップ）すると選択モーダルが開き、
//    ①カタログ馬を検索して選ぶ ②保存した自家生産馬を呼び出す
//    ③新しく自家生産馬を作る ④不明にする を切り替えられる。
//    → 候補馬が何百頭あっても、長いプルダウンをスクロールせずに済む。
//  ・カタログ馬を置いたマスは、その馬自身の血統(JSON)を薄いグレーで
//    自動展開して表示するため、どの祖先が入っているか一目で分かる。
//  ・相手側と重複する祖先（＝インブリードになる馬）はハイライト表示する。
// ============================================================

import React, { useCallback, useMemo, useState } from "react";
import { Badge, Button, Form, Modal } from "react-bootstrap";
import { HorseRecord, PedigreeKey, PedigreeNode, Sex } from "./types";
import { MAX_GEN, getThreeStarMedalCount, resolveNodeIdentity } from "./pedigreeUtils";
import { describeNode } from "./savedPedigrees";
import { collectHomebredIssues, isRelatedPath, issuePathKeys } from "./homebredValidation";

// ------------------------------------------------------------
// 型
// ------------------------------------------------------------

/** ルートからのパス。"S"=父方へ1つ, "D"=母方へ1つ。空配列＝本馬自身 */
export type NodePath = ("S" | "D")[];

/** 保存済み自家生産馬（呼び出し側で PedigreeNode に復元済みのもの） */
export interface SavedOption {
  id: string;
  name: string;
  sex: Sex;
  node: PedigreeNode;
}

interface Props {
  /** 列の見出し（"種牡馬" / "繁殖牝馬"） */
  columnLabel: string;
  /** ルートに入るべき性別 */
  requiredSex: Sex;
  catalog: HorseRecord[];
  value: PedigreeNode;
  onChange: (node: PedigreeNode) => void;
  /** 保存済みの自家生産馬（どのマスからでも呼び出せる） */
  savedOptions: SavedOption[];
  /** 相手側と重複する祖先の識別キー。ハイライト表示に使う */
  highlightKeys?: Set<string>;
  /** ツリーの複製（保存馬を読み込む際に参照を共有させないため） */
  cloneNode: (node: PedigreeNode) => PedigreeNode;
}

interface GridCell {
  key: string;
  col: number; // 0 = 本馬, 3 = 曾祖父母
  row: number; // 0..ROWS-1
  span: number;
  gen: number;
  kind: "editable" | "readonly";
  label: string;
  sub?: string;
  identityKey?: string;
  path?: NodePath;
  sex?: Sex;
  /** editable セルのみ: 中に入っている馬の種類（背景色の区別に使う） */
  nodeType?: "catalog" | "homebred" | "unknown";
}

// ------------------------------------------------------------
// 定数
// ------------------------------------------------------------

const ROWS = Math.pow(2, MAX_GEN - 1); // 8行
const GEN_HEADERS = ["本馬", "父母", "祖父母", "曾祖父母"];

const PED_KEYS: PedigreeKey[] = [
  "S", "D",
  "SS", "SD", "DS", "DD",
  "SSS", "SSD", "SDS", "SDD", "DSS", "DSD", "DDS", "DDD",
];

// ------------------------------------------------------------
// パス操作
// ------------------------------------------------------------

export function getNodeAt(root: PedigreeNode, path: NodePath): PedigreeNode | null {
  let cur: PedigreeNode | null = root;
  for (const step of path) {
    if (!cur || cur.type !== "homebred") return null;
    cur = step === "S" ? cur.sire : cur.dam;
  }
  return cur;
}

export function setNodeAt(
  root: PedigreeNode,
  path: NodePath,
  next: PedigreeNode | null
): PedigreeNode {
  if (path.length === 0) return next ?? root;
  if (root.type !== "homebred") return root;

  const [head, ...rest] = path;
  if (head === "S") {
    const child = root.sire;
    const nextChild = rest.length === 0 ? next : child ? setNodeAt(child, rest, next) : child;
    return { ...root, sire: nextChild };
  }
  const child = root.dam;
  const nextChild = rest.length === 0 ? next : child ? setNodeAt(child, rest, next) : child;
  return { ...root, dam: nextChild };
}

/** パスから見出し文字列を作る（例: ["S","D"] → "父の母"） */
function pathLabel(path: NodePath, rootLabel: string): string {
  if (path.length === 0) return rootLabel;
  return path.map((p) => (p === "S" ? "父" : "母")).join("の");
}

function defaultCatalogNode(catalog: HorseRecord[], sex: Sex): PedigreeNode | null {
  const horse = catalog.find((h) => (sex === "male" ? h.horse_type === "sire" : h.horse_type === "mare"));
  return horse ? { type: "catalog", horse } : null;
}

// ------------------------------------------------------------
// グリッドのセル構築
// ------------------------------------------------------------

function cellLabel(node: PedigreeNode | null): string {
  if (!node) return "＋ 未設定";
  if (node.type === "catalog") return node.horse.name;
  if (node.type === "unknown") return "不明";
  return node.name?.trim() || "自家生産馬";
}

function cellSub(node: PedigreeNode | null): string | undefined {
  if (!node) return undefined;
  if (node.type === "catalog") return node.horse.line;
  if (node.type === "homebred") return describeNode(node);
  return undefined;
}

function buildCells(
  node: PedigreeNode | null,
  gen: number,
  top: number,
  height: number,
  path: NodePath,
  sex: Sex,
  out: GridCell[]
): void {
  const identity = node ? resolveNodeIdentity(node) : null;
  out.push({
    key: `e-${path.join("") || "root"}`,
    col: gen - 1,
    row: top,
    span: height,
    gen,
    kind: "editable",
    label: cellLabel(node),
    sub: height >= 2 ? cellSub(node) : undefined,
    identityKey: identity?.key,
    path,
    sex,
    nodeType: node?.type,
  });

  if (!node) return;

  if (node.type === "catalog") {
    // カタログ馬は自身のJSON血統をそのまま展開（読み取り専用）
    for (const key of PED_KEYS) {
      const g = gen + key.length;
      if (g > MAX_GEN) continue;
      let row = top;
      let span = height;
      for (const ch of key) {
        span = span / 2;
        if (ch === "D") row += span;
      }
      const anc = node.horse.pedigree?.[key];
      out.push({
        key: `r-${path.join("") || "root"}-${key}`,
        col: g - 1,
        row,
        span,
        gen: g,
        kind: "readonly",
        label: anc?.name ?? "―",
        identityKey: anc?.name,
      });
    }
    return;
  }

  if (node.type === "homebred") {
    if (gen >= MAX_GEN) return;
    const half = height / 2;
    buildCells(node.sire, gen + 1, top, half, [...path, "S"], "male", out);
    buildCells(node.dam, gen + 1, top + half, half, [...path, "D"], "female", out);
  }
}

// ------------------------------------------------------------
// 選択モーダルの中身（picker が切り替わるたびに key で再マウントする）
// ------------------------------------------------------------

type PickerTab = "catalog" | "saved" | "homebred";

interface SlotPickerProps {
  gen: number;
  requiredSex: Sex;
  catalog: HorseRecord[];
  currentNode: PedigreeNode | null;
  savedOptions: SavedOption[];
  isRoot: boolean;
  onApply: (node: PedigreeNode | null) => void;
  /** その馬をこのマスに入れると「作れない自家生産馬」が生まれてしまうか */
  isCandidateBlocked: (node: PedigreeNode) => boolean;
}

const SlotPicker: React.FC<SlotPickerProps> = ({
  gen,
  requiredSex,
  catalog,
  currentNode,
  savedOptions,
  isRoot,
  onApply,
  isCandidateBlocked,
}) => {
  const [tab, setTab] = useState<PickerTab>(
    currentNode?.type === "homebred" ? "homebred" : "catalog"
  );
  const [keyword, setKeyword] = useState("");
  const [lineFilter, setLineFilter] = useState("");
  const [showOtherSexSaved, setShowOtherSexSaved] = useState(false);
  const [homebredName, setHomebredName] = useState(
    currentNode?.type === "homebred" ? currentNode.name ?? "" : ""
  );

  const sexOptions = useMemo(
    () =>
      catalog
        .map((h, idx) => ({ horse: h, idx }))
        .filter(({ horse }) =>
          requiredSex === "male" ? horse.horse_type === "sire" : horse.horse_type === "mare"
        ),
    [catalog, requiredSex]
  );

  const lineNames = useMemo(
    () => Array.from(new Set(sexOptions.map(({ horse }) => horse.line))).sort((a, b) => a.localeCompare(b, "ja")),
    [sexOptions]
  );

  const filtered = useMemo(() => {
    const kw = keyword.trim();
    return sexOptions
      .filter(({ horse }) => {
        if (kw && !horse.name.includes(kw) && !horse.line.includes(kw)) return false;
        if (lineFilter && horse.line !== lineFilter) return false;
        return true;
      })
      .sort((a, b) => a.horse.name.localeCompare(b.horse.name, "ja"));
  }, [sexOptions, keyword, lineFilter]);

  const visibleSaved = useMemo(
    () => savedOptions.filter((s) => showOtherSexSaved || s.sex === requiredSex),
    [savedOptions, showOtherSexSaved, requiredSex]
  );

  /** 選ぶと配合不可の自家生産馬ができてしまうカタログ馬（カタログ内indexの集合） */
  const blockedCatalogIdx = useMemo(() => {
    const blocked = new Set<number>();
    for (const { horse, idx } of sexOptions) {
      if (isCandidateBlocked({ type: "catalog", horse })) blocked.add(idx);
    }
    return blocked;
  }, [sexOptions, isCandidateBlocked]);

  /** 同上（保存済みの自家生産馬） */
  const blockedSavedIds = useMemo(() => {
    const blocked = new Set<string>();
    for (const s of savedOptions) {
      if (isCandidateBlocked(s.node)) blocked.add(s.id);
    }
    return blocked;
  }, [savedOptions, isCandidateBlocked]);

  const canGoDeeper = gen < MAX_GEN;

  const applyHomebred = () => {
    if (currentNode?.type === "homebred") {
      onApply({ ...currentNode, name: homebredName });
      return;
    }
    onApply({
      type: "homebred",
      name: homebredName,
      sire: canGoDeeper ? defaultCatalogNode(catalog, "male") : null,
      dam: canGoDeeper ? defaultCatalogNode(catalog, "female") : null,
    });
  };

  const tabButton = (key: PickerTab, text: string) => (
    <Button
      size="sm"
      variant={tab === key ? "dark" : "outline-dark"}
      className="fw-bold flex-fill"
      onClick={() => setTab(key)}
    >
      {text}
    </Button>
  );

  return (
    <>
      <div className="d-flex gap-1 mb-3">
        {tabButton("catalog", "カタログ馬")}
        {tabButton("saved", `保存した馬${savedOptions.length ? `(${savedOptions.length})` : ""}`)}
        {tabButton("homebred", "自家生産馬")}
      </div>

      {tab === "catalog" && (
        <>
          <Form.Control
            autoFocus
            type="search"
            placeholder="馬名・系統の一部を入力して絞り込み"
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            className="mb-2 shadow-sm"
          />
          <Form.Select
            size="sm"
            value={lineFilter}
            onChange={(e) => setLineFilter(e.target.value)}
            className="mb-2"
          >
            <option value="">系統で絞り込み（すべて）</option>
            {lineNames.map((l) => (
              <option key={l} value={l}>
                {l}
              </option>
            ))}
          </Form.Select>

          <div className="text-muted small mb-1">{filtered.length}頭</div>
          <div style={{ maxHeight: "46vh", overflowY: "auto", border: "1px solid #dee2e6", borderRadius: "8px" }}>
            {filtered.map(({ horse, idx }) => {
              const isCurrent = currentNode?.type === "catalog" && currentNode.horse === horse;
              const medal = getThreeStarMedalCount(horse);
              const blocked = blockedCatalogIdx.has(idx);
              return (
                <div
                  key={idx}
                  role="button"
                  onClick={() => onApply({ type: "catalog", horse })}
                  title={blocked ? "この馬を入れると配合不可の自家生産馬になります" : undefined}
                  className="d-flex align-items-center justify-content-between px-3 py-2"
                  style={{
                    cursor: "pointer",
                    borderBottom: "1px solid #f1f1f1",
                    backgroundColor: blocked ? "#fdf0ef" : isCurrent ? "#ffe9e9" : "#fff",
                  }}
                >
                  <div className="text-truncate">
                    <span className="fw-bold" style={{ color: blocked ? "#9b8f8d" : undefined }}>
                      {horse.name}
                    </span>
                    <span className="text-muted small ms-2">{horse.line}</span>
                  </div>
                  <div className="d-flex align-items-center gap-2 flex-shrink-0 ms-2">
                    {blocked && <Badge bg="danger">配合不可</Badge>}
                    {medal !== null && (
                      <Badge bg="warning" text="dark">
                        ★3 {medal}
                      </Badge>
                    )}
                  </div>
                </div>
              );
            })}
            {filtered.length === 0 && (
              <div className="text-center text-muted py-4 small">該当する馬がいません</div>
            )}
          </div>
        </>
      )}

      {tab === "saved" && (
        <>
          {savedOptions.length === 0 ? (
            <div className="text-muted small p-3 text-center" style={{ backgroundColor: "#f8f9fa", borderRadius: "8px" }}>
              保存された自家生産馬はまだありません。<br />
              血統を組んだあと「この血統を保存」から登録できます（最大5頭）。
            </div>
          ) : (
            <>
              <Form.Check
                type="switch"
                id={`other-sex-saved-${gen}-${requiredSex}`}
                className="mb-2 small"
                label="別の性別で保存した馬も表示する"
                checked={showOtherSexSaved}
                onChange={(e) => setShowOtherSexSaved(e.currentTarget.checked)}
              />
              <div style={{ maxHeight: "46vh", overflowY: "auto" }}>
                {visibleSaved.map((s) => {
                  const blocked = blockedSavedIds.has(s.id);
                  return (
                    <div
                      key={s.id}
                      role="button"
                      onClick={() => onApply(s.node)}
                      title={blocked ? "この馬を入れると配合不可の自家生産馬になります" : undefined}
                      className="px-3 py-2 mb-2 shadow-sm"
                      style={{
                        cursor: "pointer",
                        backgroundColor: blocked ? "#fdf0ef" : "#fff",
                        border: blocked ? "1px solid #f1aeae" : "1px solid #dee2e6",
                        borderRadius: "8px",
                      }}
                    >
                      <div className="fw-bold">
                        {s.name}
                        <Badge bg="secondary" className="ms-2">
                          {s.sex === "male" ? "種牡馬側" : "繁殖牝馬側"}
                        </Badge>
                        {blocked && <Badge bg="danger" className="ms-2">配合不可</Badge>}
                      </div>
                      <div className="text-muted small text-truncate">{describeNode(s.node)}</div>
                    </div>
                  );
                })}
                {visibleSaved.length === 0 && (
                  <div className="text-center text-muted py-3 small">
                    この性別で保存された馬はありません
                  </div>
                )}
              </div>
            </>
          )}
        </>
      )}

      {tab === "homebred" && (
        <>
          <Form.Label className="small fw-bold text-muted">馬名（任意）</Form.Label>
          <Form.Control
            autoFocus
            placeholder="例: 自家生産馬A"
            value={homebredName}
            onChange={(e) => setHomebredName(e.target.value)}
            className="mb-2 shadow-sm"
          />
          <div className="text-muted small mb-3">
            {canGoDeeper
              ? "父・母は血統表のマスから続けて指定できます。名前を入力しなくても、父・母が同じ組み合わせなら同一個体として重複判定されます。"
              : `${MAX_GEN}代目のため父・母は判定対象外です。名前を入力した場合のみ、同名の自家生産馬同士を同一個体として扱います。`}
          </div>
          <Button variant="dark" className="w-100 fw-bold" onClick={applyHomebred}>
            {currentNode?.type === "homebred" ? "名前を更新する" : "このマスを自家生産馬にする"}
          </Button>
        </>
      )}

      {!isRoot && (
        <Button variant="outline-secondary" size="sm" className="w-100 mt-3" onClick={() => onApply({ type: "unknown" })}>
          不明にする（この先の代を判定から除外）
        </Button>
      )}
    </>
  );
};

// ------------------------------------------------------------
// 本体
// ------------------------------------------------------------

const PedigreeGridSelector: React.FC<Props> = ({
  columnLabel,
  requiredSex,
  catalog,
  value,
  onChange,
  savedOptions,
  highlightKeys,
  cloneNode,
}) => {
  const [picker, setPicker] = useState<{ path: NodePath; gen: number; sex: Sex } | null>(null);

  const cells = useMemo(() => {
    const out: GridCell[] = [];
    buildCells(value, 1, 0, ROWS, [], requiredSex, out);
    return out;
  }, [value, requiredSex]);

  // 「その自家生産馬は父×母の組み合わせ的に生産できない」ケースの検出
  const issues = useMemo(() => collectHomebredIssues(value), [value]);
  const issueKeys = useMemo(() => issuePathKeys(issues), [issues]);
  const issueByKey = useMemo(() => {
    const m = new Map<string, string>();
    issues.forEach((i) => m.set(i.path.join("") || "root", i.reason));
    return m;
  }, [issues]);

  /** 選択モーダル用: その馬をこのマスに入れると配合不可の自家生産馬ができるか */
  const isCandidateBlocked = useCallback(
    (candidate: PedigreeNode) => {
      if (!picker) return false;
      const hypothetical =
        picker.path.length === 0 ? candidate : setNodeAt(value, picker.path, candidate);
      return collectHomebredIssues(hypothetical).some((iss) =>
        isRelatedPath(iss.path, picker.path)
      );
    },
    [picker, value]
  );

  const highlightCount = useMemo(() => {
    if (!highlightKeys || highlightKeys.size === 0) return 0;
    const seen = new Set<string>();
    for (const c of cells) {
      if (c.identityKey && highlightKeys.has(c.identityKey)) seen.add(c.identityKey);
    }
    return seen.size;
  }, [cells, highlightKeys]);

  const currentPickerNode = picker ? getNodeAt(value, picker.path) : null;

  const applyNode = (node: PedigreeNode | null) => {
    if (!picker) return;
    const cloned = node ? cloneNode(node) : null;
    if (picker.path.length === 0) {
      if (cloned) onChange(cloned);
    } else {
      onChange(setNodeAt(value, picker.path, cloned));
    }
    setPicker(null);
  };

  return (
    <>
      {/* 見出し行 */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: `repeat(${MAX_GEN}, minmax(84px, 1fr))`,
          gap: "2px",
          minWidth: `${MAX_GEN * 86}px`,
        }}
      >
        {GEN_HEADERS.map((h) => (
          <div
            key={h}
            className="text-center fw-bold"
            style={{ fontSize: "10px", color: "#0d47a1", padding: "2px 0" }}
          >
            {h}
          </div>
        ))}
      </div>

      {/* 血統表グリッド */}
      <div style={{ overflowX: "auto" }}>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: `repeat(${MAX_GEN}, minmax(84px, 1fr))`,
            gridTemplateRows: `repeat(${ROWS}, 30px)`,
            gap: "2px",
            minWidth: `${MAX_GEN * 86}px`,
          }}
        >
          {cells.map((c) => {
            const highlighted = !!(c.identityKey && highlightKeys?.has(c.identityKey));
            const editable = c.kind === "editable";
            const cellKey = c.path ? c.path.join("") || "root" : "";
            const invalid = editable && issueKeys.has(cellKey);
            return (
              <div
                key={c.key}
                role={editable ? "button" : undefined}
                title={
                  invalid
                    ? `配合不可: ${issueByKey.get(cellKey)}`
                    : c.sub
                    ? `${c.label}（${c.sub}）`
                    : c.label
                }
                onClick={
                  editable && c.path && c.sex
                    ? () => setPicker({ path: c.path!, gen: c.gen, sex: c.sex! })
                    : undefined
                }
                style={{
                  gridColumn: c.col + 1,
                  gridRow: `${c.row + 1} / span ${c.span}`,
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "center",
                  alignItems: "flex-start",
                  padding: "2px 5px",
                  overflow: "hidden",
                  borderRadius: "5px",
                  cursor: editable ? "pointer" : "default",
                  backgroundColor: invalid
                    ? "#f8d7da"
                    : highlighted
                    ? "#fff3cd"
                    : editable
                    ? c.nodeType === "catalog"
                      ? "#e6f0fa"
                      : c.nodeType === "homebred"
                      ? "#fdf6e0"
                      : "#ffffff"
                    : "#f5f6f8",
                  border: invalid
                    ? "2px solid #d32f2f"
                    : highlighted
                    ? "2px solid #ff9800"
                    : editable
                    ? "1px solid #5c8fc4"
                    : "1px solid #e4e6ea",
                  color: invalid ? "#b71c1c" : editable ? "#212529" : "#6c757d",
                  fontSize: editable ? "11px" : "10px",
                  fontWeight: editable ? 700 : 400,
                  lineHeight: 1.2,
                }}
              >
                <span
                  style={{
                    width: "100%",
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  {invalid ? "⚠ " : ""}
                  {c.label}
                </span>
                {c.sub && (
                  <span
                    style={{
                      width: "100%",
                      fontSize: "9px",
                      fontWeight: 400,
                      color: "#8a8f98",
                      whiteSpace: "nowrap",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                    }}
                  >
                    {c.sub}
                  </span>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {issues.length > 0 && (
        <div
          className="mt-2 px-3 py-2"
          style={{
            backgroundColor: "#f8d7da",
            border: "1px solid #f1aeae",
            borderRadius: "8px",
            color: "#b71c1c",
            fontSize: "11.5px",
            lineHeight: 1.6,
          }}
        >
          <div className="fw-bold mb-1">⚠ 生産できない自家生産馬が含まれています</div>
          {issues.map((iss, i) => (
            <div key={i}>
              ・{iss.positionLabel}（{iss.horseLabel}）: {iss.reason}
            </div>
          ))}
          <div className="mt-1" style={{ fontSize: "10.5px", opacity: 0.85 }}>
            該当する馬の父・母を変更してください。解消するまで保存と判定はできません。
          </div>
        </div>
      )}

      <div className="text-muted mt-2" style={{ fontSize: "10px", lineHeight: 1.5 }}>
        <span style={{ display: "inline-block", width: "10px", height: "10px", border: "1px solid #5c8fc4", backgroundColor: "#e6f0fa", verticalAlign: "-1px" }} />
        {" 青＝カタログ馬 / "}
        <span style={{ display: "inline-block", width: "10px", height: "10px", border: "1px solid #5c8fc4", backgroundColor: "#fdf6e0", verticalAlign: "-1px" }} />
        {" クリーム＝自家生産馬（いずれもクリックで変更可） / "}
        <span style={{ display: "inline-block", width: "10px", height: "10px", border: "1px solid #e4e6ea", backgroundColor: "#f5f6f8", verticalAlign: "-1px" }} />
        {" グレー＝カタログ馬の血統（自動）"}
        {highlightKeys && highlightKeys.size > 0 && (
          <>
            {" / "}
            <span style={{ display: "inline-block", width: "10px", height: "10px", border: "2px solid #ff9800", backgroundColor: "#fff3cd", verticalAlign: "-1px" }} />
            {` オレンジ枠＝相手側と重複する祖先（${highlightCount}頭）`}
          </>
        )}
      </div>

      <Modal show={picker !== null} onHide={() => setPicker(null)} centered size="lg" scrollable>
        <Modal.Header closeButton style={{ backgroundColor: "#1565c0", color: "#fff" }}>
          <Modal.Title style={{ fontSize: "1.05em" }}>
            {columnLabel}：{picker ? pathLabel(picker.path, "本馬") : ""} を選択
            {picker && <Badge bg="light" text="dark" className="ms-2">{picker.gen}代目</Badge>}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {picker && (
            <SlotPicker
              key={picker.path.join("") || "root"}
              gen={picker.gen}
              requiredSex={picker.sex}
              catalog={catalog}
              currentNode={currentPickerNode}
              savedOptions={savedOptions}
              isRoot={picker.path.length === 0}
              onApply={applyNode}
              isCandidateBlocked={isCandidateBlocked}
            />
          )}
        </Modal.Body>
      </Modal>
    </>
  );
};

export default PedigreeGridSelector;
