import React, { useState, useEffect } from 'react';
import { Container, Table, Badge, Spinner, Alert } from 'react-bootstrap';
import { NOTION_API_KEY, NOTION_DB_ID } from "./config";
// 型定義
interface NotionRecord {
  id: string;
  fileName: string;
  qrFileName: string;
  readData: string;
  category: string;
  count: number;
  updatedAt: string;
}

const QrUpdate: React.FC = () => {
  const [data, setData] = useState<NotionRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const API_KEY = NOTION_API_KEY;
  const DB_ID = NOTION_DB_ID;

  useEffect(() => {
    const fetchData = async () => {
      if (!API_KEY || !DB_ID) {
        setError("環境変数 (REACT_APP_...) が設定されていません。");
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        
// URLの先頭に corsproxy.io を追加して直接通信します
        const response = await fetch(`https://corsproxy.io/?https://api.notion.com/v1/databases/${DB_ID}/query`, {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${API_KEY}`,
            'Notion-Version': '2022-06-28',
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({}), 
        });

        if (!response.ok) {
            const errorData = await response.json();
            console.error("★★★ Notionからの詳細エラー ★★★", errorData);
            throw new Error(`エラーコード: ${errorData.code}\n理由: ${errorData.message}`);
        }

        const result = await response.json();
        
        const formattedData = result.results.map((page: any) => {
          const p = page.properties;
          return {
            id: page.id,
            fileName: p["画像ファイル名"]?.title[0]?.plain_text || "未設定",
            qrFileName: p["QRファイル名"]?.rich_text[0]?.plain_text || "未設定",
            readData: p["読み取りデータ"]?.rich_text[0]?.plain_text || "---",
            category: p["分類"]?.select?.name || "未分類",
            count: p["カウント"]?.number || 0,
            updatedAt: p["更新日"]?.date?.start || "不明",
          };
        });

        setData(formattedData);
      } catch (err: any) {
        console.error(err);
        setError("データの取得に失敗しました。CORSエラーが起きている可能性があります。");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [API_KEY, DB_ID]);

  return (
    <Container className="mt-5">
      <h2 className="text-center mb-4">QRシステム連携データベース</h2>
      
      {loading ? (
        <div className="text-center py-5"><Spinner animation="border" /></div>
      ) : error ? (
        <Alert variant="danger">{error} <br/> <small>※ブラウザのコンソール(F12)で詳細を確認してください。</small></Alert>
      ) : (
        <Table striped bordered hover responsive className="shadow-sm">
          <thead className="table-dark">
            <tr>
              <th>画像ファイル名</th>
              <th>QRファイル名</th>
              <th>読み取りデータ</th>
              <th>分類</th>
              <th>カウント</th>
              <th>更新日</th>
            </tr>
          </thead>
          <tbody>
            {data.map((item) => (
              <tr key={item.id}>
                <td className="fw-bold">{item.fileName}</td>
                <td>{item.qrFileName}</td>
                <td><code>{item.readData}</code></td>
                <td><Badge bg="info">{item.category}</Badge></td>
                <td className="text-center">{item.count}</td>
                <td>{item.updatedAt}</td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
    </Container>
  );
};

export default QrUpdate;