// ============================================================
// savedPedigrees.ts
// 「自家生産馬」の血統ツリーをブラウザに保存／復元するユーティリティ。
//
//  ・保存先は localStorage（キー: sh3_saved_pedigrees_v1）。
//    localStorage が使えない環境（プライベートモード等）では
//    自動的に Cookie にフォールバックする。
//  ・保存できるのは最大 5 頭（MAX_SAVED_PEDIGREES）。
//  ・PedigreeNode は HorseRecord オブジェクトへの参照を持っているため
//    そのままでは JSON 化しても復元できない。カタログ馬は
//    「馬名 + 種別 + カタログ内index」で保存し、読み込み時に
//    HORSE_CATALOG から引き直す（indexが一致しなければ名前で再検索）。
// ============================================================

import { HorseRecord, PedigreeNode, Sex } from "./types";

const STORAGE_KEY = "sh3_saved_pedigrees_v1";
/** Cookie に書き出す際の上限（Cookie全体で約4KBのため余裕を持たせる） */
const COOKIE_MAX_BYTES = 3500;
const COOKIE_DAYS = 400;

/** 保存できる自家生産馬の最大数 */
export const MAX_SAVED_PEDIGREES = 5;

// ------------------------------------------------------------
// 保存用の軽量フォーマット
// ------------------------------------------------------------

export type StoredNode =
  | { t: "c"; n: string; h: "sire" | "mare"; i: number } // カタログ馬
  | { t: "h"; nm: string; s: StoredNode | null; d: StoredNode | null } // 自家生産馬
  | { t: "u" }; // 不明

export interface SavedPedigree {
  id: string;
  /** ユーザーが付けた名前（例: "自家生産馬A"） */
  name: string;
  /** 種牡馬側で作ったか繁殖牝馬側で作ったか */
  sex: Sex;
  updatedAt: number;
  node: StoredNode;
}

// ------------------------------------------------------------
// シリアライズ / デシリアライズ
// ------------------------------------------------------------

export function serializeNode(node: PedigreeNode, catalog: HorseRecord[]): StoredNode {
  if (node.type === "catalog") {
    return {
      t: "c",
      n: node.horse.name,
      h: node.horse.horse_type,
      i: catalog.indexOf(node.horse),
    };
  }
  if (node.type === "homebred") {
    return {
      t: "h",
      nm: node.name ?? "",
      s: node.sire ? serializeNode(node.sire, catalog) : null,
      d: node.dam ? serializeNode(node.dam, catalog) : null,
    };
  }
  return { t: "u" };
}

export function deserializeNode(
  stored: StoredNode | null | undefined,
  catalog: HorseRecord[]
): PedigreeNode | null {
  if (!stored) return null;

  if (stored.t === "c") {
    // 同名馬が複数存在しうるため、まずindexで引き当てる（名前と種別が一致する場合のみ採用）
    const byIndex =
      typeof stored.i === "number" && stored.i >= 0 && stored.i < catalog.length
        ? catalog[stored.i]
        : undefined;
    const horse =
      byIndex && byIndex.name === stored.n && byIndex.horse_type === stored.h
        ? byIndex
        : catalog.find((h) => h.name === stored.n && h.horse_type === stored.h);
    return horse ? { type: "catalog", horse } : null;
  }

  if (stored.t === "h") {
    return {
      type: "homebred",
      name: stored.nm ?? "",
      sire: deserializeNode(stored.s, catalog),
      dam: deserializeNode(stored.d, catalog),
    };
  }

  return { type: "unknown" };
}

/** ツリーの完全なコピーを作る（保存馬を読み込む際に参照を共有させないため） */
export function cloneNode(node: PedigreeNode, catalog: HorseRecord[]): PedigreeNode {
  return deserializeNode(serializeNode(node, catalog), catalog) ?? node;
}

/** 一覧表示用の短い説明文（例: "サンデーサイレンス × ダイナカール"） */
export function describeNode(node: PedigreeNode | null | undefined, depth = 0): string {
  if (!node) return "未設定";
  if (node.type === "catalog") return node.horse.name;
  if (node.type === "unknown") return "不明";
  if (depth >= 1) return node.name?.trim() || "自家生産馬";
  return `${describeNode(node.sire, depth + 1)} × ${describeNode(node.dam, depth + 1)}`;
}

// ------------------------------------------------------------
// ストレージ（localStorage → 失敗時 Cookie）
// ------------------------------------------------------------

function readCookie(name: string): string | null {
  if (typeof document === "undefined") return null;
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const m = document.cookie.match(new RegExp("(?:^|; )" + escaped + "=([^;]*)"));
  return m ? decodeURIComponent(m[1]) : null;
}

function writeCookie(name: string, value: string): void {
  if (typeof document === "undefined") return;
  const enc = encodeURIComponent(value);
  if (enc.length > COOKIE_MAX_BYTES) return; // 大きすぎる場合はCookieには載せない
  const expires = new Date(Date.now() + COOKIE_DAYS * 864e5).toUTCString();
  document.cookie = `${name}=${enc}; expires=${expires}; path=/; SameSite=Lax`;
}

function readRaw(): string | null {
  try {
    const v = window.localStorage.getItem(STORAGE_KEY);
    if (v !== null) return v;
  } catch {
    /* localStorage が使えない環境 */
  }
  return readCookie(STORAGE_KEY);
}

function writeRaw(value: string): void {
  let stored = false;
  try {
    window.localStorage.setItem(STORAGE_KEY, value);
    stored = true;
  } catch {
    /* 容量オーバー / プライベートモード等 */
  }
  // localStorage が使えなかった場合の保険として Cookie にも書いておく
  if (!stored) writeCookie(STORAGE_KEY, value);
}

function isStoredNode(v: unknown): v is StoredNode {
  if (!v || typeof v !== "object") return false;
  const t = (v as { t?: unknown }).t;
  return t === "c" || t === "h" || t === "u";
}

/** 保存済み一覧を読み込む（壊れたデータは黙って捨てる） */
export function loadSavedPedigrees(): SavedPedigree[] {
  const raw = readRaw();
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter(
        (p): p is SavedPedigree =>
          !!p &&
          typeof p.id === "string" &&
          typeof p.name === "string" &&
          (p.sex === "male" || p.sex === "female") &&
          isStoredNode(p.node)
      )
      .slice(0, MAX_SAVED_PEDIGREES);
  } catch {
    return [];
  }
}

/** 保存済み一覧を書き出す */
export function persistSavedPedigrees(list: SavedPedigree[]): void {
  try {
    writeRaw(JSON.stringify(list.slice(0, MAX_SAVED_PEDIGREES)));
  } catch {
    /* 保存できなくても画面の動作は継続する */
  }
}

export function makeSavedId(): string {
  return `sp_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
}

/** "自家生産馬A" のような未使用のデフォルト名を作る */
export function suggestSavedName(existing: SavedPedigree[]): string {
  const used = new Set(existing.map((s) => s.name));
  for (const ch of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") {
    const candidate = `自家生産馬${ch}`;
    if (!used.has(candidate)) return candidate;
  }
  return `自家生産馬${existing.length + 1}`;
}
